create table public.feature_flags (key text primary key,description text,enabled boolean not null default false,rules jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,event_type text not null,object_type text,object_id uuid,request_id text,ip_hash text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.api_keys (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,key_prefix text not null,key_hash text not null unique,scopes text[] not null,revoked_at timestamptz,last_used_at timestamptz,created_at timestamptz not null default now());
create table public.webhooks (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,url text not null,secret_hash text not null,secret_ciphertext text not null,events text[] not null,enabled boolean not null default true,created_at timestamptz not null default now());
create table public.webhook_deliveries (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,webhook_id uuid not null references public.webhooks(id) on delete cascade,event_id text not null,event_type text not null,payload jsonb not null,status text not null default 'pending' check(status in('pending','delivered','retrying','failed')),attempts integer not null default 0,next_attempt_at timestamptz,response_status integer,last_error text,created_at timestamptz not null default now(),delivered_at timestamptz,unique(webhook_id,event_id));
create table public.background_jobs (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,job_type text not null,payload jsonb not null,status text not null default 'pending' check(status in('pending','running','completed','failed','dead')),attempts integer not null default 0,max_attempts integer not null default 5,run_after timestamptz not null default now(),locked_at timestamptz,locked_by text,last_error text,created_at timestamptz not null default now(),completed_at timestamptz,idempotency_key text unique);
create table public.rate_limit_windows (key_hash text not null,window_start timestamptz not null,count integer not null default 1,primary key(key_hash,window_start));
alter table public.feature_flags enable row level security;alter table public.audit_events enable row level security;alter table public.api_keys enable row level security;alter table public.webhooks enable row level security;alter table public.webhook_deliveries enable row level security;alter table public.background_jobs enable row level security;alter table public.rate_limit_windows enable row level security;
create policy feature_flags_read on public.feature_flags for select to authenticated using(enabled=true);create policy audit_own_read on public.audit_events for select to authenticated using(user_id=(select auth.uid()));
do $$ declare t text;begin foreach t in array array['api_keys','webhooks','webhook_deliveries'] loop execute format('create policy %I on public.%I for select to authenticated using(user_id=(select auth.uid()))',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(user_id=(select auth.uid()))',t||'_insert',t);execute format('create policy %I on public.%I for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()))',t||'_update',t);end loop;end $$;
create policy webhooks_delete on public.webhooks for delete to authenticated using(user_id=(select auth.uid()));
grant select on public.feature_flags,public.audit_events to authenticated;grant select,insert,update,delete on public.api_keys,public.webhooks to authenticated;grant select on public.webhook_deliveries to authenticated;
create index audit_user_time_idx on public.audit_events(user_id,created_at desc);create index jobs_ready_idx on public.background_jobs(status,run_after) where status in('pending','failed');create index webhook_delivery_ready_idx on public.webhook_deliveries(status,next_attempt_at) where status in('pending','retrying');create index api_keys_user_active_idx on public.api_keys(user_id) where revoked_at is null;

create or replace function public.write_audit_event(p_event_type text,p_object_type text,p_object_id uuid,p_request_id text,p_metadata jsonb) returns uuid language plpgsql security invoker set search_path='' as $$ declare result uuid;begin insert into public.audit_events(user_id,event_type,object_type,object_id,request_id,metadata) values((select auth.uid()),p_event_type,p_object_type,p_object_id,p_request_id,coalesce(p_metadata,'{}')) returning id into result;return result;end $$;
create or replace function public.consume_rate_limit(p_key_hash text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path='' as $$ declare bucket timestamptz;current_count integer;begin bucket=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds);insert into public.rate_limit_windows(key_hash,window_start,count) values(p_key_hash,bucket,1) on conflict(key_hash,window_start) do update set count=public.rate_limit_windows.count+1 returning count into current_count;return current_count<=p_limit;end $$;
create or replace function public.enqueue_webhook_event() returns trigger language plpgsql security definer set search_path='' as $$ declare owner uuid;kind text;event_key text;body jsonb;begin if tg_table_name='activities' then owner=new.user_id;kind='activity.created';event_key='activity.created:'||new.id;body=jsonb_build_object('id',new.id,'description',new.description,'occurredAt',new.occurred_at);elsif tg_table_name='achievement_unlocks' then owner=new.user_id;kind='achievement.unlocked';event_key='achievement.unlocked:'||new.id;body=jsonb_build_object('id',new.id,'achievementKey',new.achievement_key,'unlockedAt',new.unlocked_at);elsif tg_table_name='goals' and new.status='completed' and old.status is distinct from new.status then owner=new.user_id;kind='goal.completed';event_key='goal.completed:'||new.id;body=jsonb_build_object('id',new.id,'title',new.title,'completedAt',now());else return new;end if;insert into public.webhook_deliveries(user_id,webhook_id,event_id,event_type,payload) select owner,w.id,event_key,kind,jsonb_build_object('id',event_key,'type',kind,'createdAt',now(),'data',body) from public.webhooks w where w.user_id=owner and w.enabled and kind=any(w.events) on conflict do nothing;return new;end $$;
create trigger activity_webhooks after insert on public.activities for each row execute function public.enqueue_webhook_event();create trigger achievement_webhooks after insert on public.achievement_unlocks for each row execute function public.enqueue_webhook_event();create trigger goal_webhooks after update of status on public.goals for each row execute function public.enqueue_webhook_event();
revoke all on function public.write_audit_event(text,text,uuid,text,jsonb),public.consume_rate_limit(text,integer,integer) from public,anon;grant execute on function public.write_audit_event(text,text,uuid,text,jsonb),public.consume_rate_limit(text,integer,integer) to authenticated;
revoke all on public.background_jobs,public.rate_limit_windows from anon,authenticated;
revoke all on function public.enqueue_webhook_event() from public,anon,authenticated;
insert into public.feature_flags(key,description,enabled) values('friends','Friend connections',true),('challenges','Private challenges',true),('public_profiles','Opt-in profile sharing',true),('ai_planner','AI-assisted planning',false) on conflict(key) do nothing;
